-- Neo Tokyo Racers - Owned Garage Style UX and stable preview lifecycle V1
-- Run once in the Roblox Studio Command Bar while NOT playing.
-- One transactional install: icons, shop states, bulk styling, responsive layout and flicker-safe presentation.

local RunService=game:GetService("RunService")
assert(not RunService:IsRunning(),"Run this installer in Roblox Studio Edit mode.")
local HttpService=game:GetService("HttpService")
local ReplicatedStorage=game:GetService("ReplicatedStorage")
local ServerScriptService=game:GetService("ServerScriptService")
local StarterPlayer=game:GetService("StarterPlayer")

local TAG="[NTR Owned Garage Style UX V1]"
local BASE="NTR_OWNED_GARAGE_ICON_CONFIG_V1_1_LOCATION_SCALE"
local REVISION="NTR_OWNED_GARAGE_STYLE_UX_V1_BATCH_STABLE_PREVIEW"
local RUN_ID=HttpService:GenerateGUID(false)

local function find(root,path) local object=root; for segment in string.gmatch(path,"[^.]+") do object=object and object:FindFirstChild(segment) end; return object end
local function count(source,needle) local result=0; local cursor=1; while true do local a,b=source:find(needle,cursor,true); if not a then return result end; result+=1; cursor=b+1 end end
local function replaceOnce(source,needle,replacement,label) local n=count(source,needle); assert(n==1,label.." anchor count was "..n); local a,b=source:find(needle,1,true); return source:sub(1,a-1)..replacement..source:sub(b+1) end
local function replaceBetween(source,first,last,replacement,label) local n=count(source,first); local m=count(source,last); assert(n==1 and m==1,label.." boundary counts were "..n.."/"..m); local a=assert(source:find(first,1,true)); local b=assert(source:find(last,a+#first,true)); return source:sub(1,a-1)..replacement..source:sub(b) end
local function compile(source,name) local fn,problem=loadstring(source,"="..name); assert(fn,name.." compile failed: "..tostring(problem)) end

local kit=assert(ReplicatedStorage:FindFirstChild("NeoTokyoRacers"),"NeoTokyoRacers missing")
local replacement=assert(find(kit,"Config.UI.GarageReplacement"),"GarageReplacement config missing")
local icons=assert(replacement:FindFirstChild("OwnedGarageIcons"),"Install and mirror Owned Garage Icon Config V1.1 first")
local uiRoot=assert(find(StarterPlayer,"StarterPlayerScripts.NeoTokyoRacersClient.Controllers.UI"),"Client UI controllers missing")
local garageRoot=assert(find(ServerScriptService,"NeoTokyoRacers.Services.Garage"),"Server garage services missing")
local owned=assert(uiRoot:FindFirstChild("OwnedGarageWorkspaceController"),"OwnedGarageWorkspaceController missing")
local workspaceController=assert(uiRoot:FindFirstChild("GarageWorkspaceController"),"GarageWorkspaceController missing")
local shared=assert(uiRoot:FindFirstChild("GarageReplacementComponents"),"GarageReplacementComponents missing")
local management=assert(garageRoot:FindFirstChild("OwnedGarageManagementRuntime"),"OwnedGarageManagementRuntime missing")
local profile=assert(garageRoot:FindFirstChild("OwnedGarageProfileRuntime"),"OwnedGarageProfileRuntime missing")
local containers={owned,workspaceController,shared,management,profile}
for _,container in ipairs(containers) do assert(container:IsA("LuaSourceContainer"),container:GetFullName().." is not a source container"); compile(container.Source,container.Name) end
assert(owned.Source:find(BASE,1,true),"Fresh V1.1 owned workspace marker missing")

local projected={}

