projected[owned]=projectOwned(owned.Source)
projected[workspaceController]=projectWorkspace(workspaceController.Source)
projected[shared]=projectShared(shared.Source)
projected[management]=projectManagement(management.Source)
projected[profile]=projectProfile(profile.Source)
assert(projected[owned]:find('Id="__ALL_STRUCTURE"',1,true) and projected[owned]:find('Id="__ALL_DECORATIONS"',1,true),"Bulk style navigation projection missing")
assert(projected[owned]:find('PriceColor=',1,true) and projected[owned]:find('NavigationSave',1,true),"Shop/icon projection missing")
assert(projected[management]:find('PreviewStructureFinishAll',1,true) and projected[management]:find('CancelAllPreviews',1,true),"Batch preview lifecycle projection missing")
assert(not projected[management]:find('runtime:ClearAllChildren()',1,true),"Destructive presentation rebuild survived projection")
assert(projected[profile]:find('action=="SetFinishAll"',1,true),"Atomic bulk finish command projection missing")

local configDefaults={
	Actions={Colour=tostring(replacement:GetAttribute("ModuleColourIcon") or ""),Material=""},
	Navigation={Save=""},
	States={Locked=tostring(replacement:GetAttribute("ModuleLockIcon") or "")},
	StructureLocations={AllStructure=""},
	DecorationLocations={AllDecorations=""},
	Materials={CONCRETE="",METAL="",WOOD="",PAINT="",TILES_A="",TILES_B="",TILES_C="",TILES_D="",TILES_E="",TILES_F=""},
}

local originalSources={}; local originalSourceAttrs={}
for container in pairs(projected) do originalSources[container]=container.Source; originalSourceAttrs[container]={Revision=container:GetAttribute("OwnedGarageStyleUxRevision"),RunId=container:GetAttribute("OwnedGarageStyleUxRunId")} end
local rootAttrs={ContractVersion=icons:GetAttribute("ContractVersion"),Revision=icons:GetAttribute("Revision"),InstallRunId=icons:GetAttribute("InstallRunId"),EditNote=icons:GetAttribute("EditNote")}
local configSnapshots={}
for group,values in pairs(configDefaults) do local folder=icons:FindFirstChild(group); assert(not folder or folder:IsA("Folder"),group.." icon config is not a Folder"); local snapshot={Folder=folder,Values={}}; if folder then for key in pairs(values) do snapshot.Values[key]=folder:GetAttribute(key) end end; configSnapshots[group]=snapshot end
local layoutAttrs={MaterialRailTabClearance=replacement:GetAttribute("MaterialRailTabClearance"),OwnedGarageUnaffordablePriceColor=replacement:GetAttribute("OwnedGarageUnaffordablePriceColor")}

local ok,problem=pcall(function()
	for group,values in pairs(configDefaults) do local folder=icons:FindFirstChild(group); if not folder then folder=Instance.new("Folder"); folder.Name=group; folder.Parent=icons end; for key,value in pairs(values) do if folder:GetAttribute(key)==nil then folder:SetAttribute(key,value) end; assert(type(folder:GetAttribute(key))=="string",group.."."..key.." must be a String attribute") end end
	if replacement:GetAttribute("MaterialRailTabClearance")==nil then replacement:SetAttribute("MaterialRailTabClearance",48) end
	if replacement:GetAttribute("OwnedGarageUnaffordablePriceColor")==nil then replacement:SetAttribute("OwnedGarageUnaffordablePriceColor",Color3.fromRGB(255,75,85)) end
	icons:SetAttribute("ContractVersion",3); icons:SetAttribute("Revision",REVISION); icons:SetAttribute("InstallRunId",RUN_ID); icons:SetAttribute("EditNote","Owned-garage icon folders include Save, Colour, Material, Locked, All locations and one icon per material. Blank values retain documented fallbacks.")
	for container,source in pairs(projected) do if container.Source~=source then container.Source=source end; container:SetAttribute("OwnedGarageStyleUxRevision",REVISION); container:SetAttribute("OwnedGarageStyleUxRunId",RUN_ID); assert(container.Source:find(REVISION,1,true),container.Name.." revision did not persist"); compile(container.Source,container.Name) end
	assert(icons.Actions:GetAttribute("Colour")~=nil and icons.Navigation:GetAttribute("Save")~=nil and icons.Materials:GetAttribute("TILES_F")~=nil,"Style icon configuration did not persist")
end)
if not ok then
	for container,source in pairs(originalSources) do pcall(function() local attrs=originalSourceAttrs[container]; container.Source=source; container:SetAttribute("OwnedGarageStyleUxRevision",attrs.Revision); container:SetAttribute("OwnedGarageStyleUxRunId",attrs.RunId) end) end
	pcall(function()
		for group,values in pairs(configDefaults) do local snapshot=configSnapshots[group]; local folder=icons:FindFirstChild(group); if not snapshot.Folder then if folder then folder:Destroy() end else for key in pairs(values) do snapshot.Folder:SetAttribute(key,snapshot.Values[key]) end end end
		icons:SetAttribute("ContractVersion",rootAttrs.ContractVersion); icons:SetAttribute("Revision",rootAttrs.Revision); icons:SetAttribute("InstallRunId",rootAttrs.InstallRunId); icons:SetAttribute("EditNote",rootAttrs.EditNote)
		replacement:SetAttribute("MaterialRailTabClearance",layoutAttrs.MaterialRailTabClearance); replacement:SetAttribute("OwnedGarageUnaffordablePriceColor",layoutAttrs.OwnedGarageUnaffordablePriceColor)
	end)
	error(TAG.." INSTALL ROLLED BACK: "..tostring(problem))
end

local writes=0; for container,source in pairs(projected) do if originalSources[container]~=source then writes+=1 end end
print(TAG.." PASS sourceWrites="..writes.." iconGroups=12 iconSlots=46 schemaMigration=false remoteAdded=false revision="..REVISION.." runId="..RUN_ID)
print(TAG.." READY: restart Studio, test stable previews, shared shop pricing, bulk Style editing and responsive navigation, then refresh the full mirror.")
